import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";

export interface StoredBlob {
  body: ReadableStream | ArrayBuffer;
  contentType: string;
}

/** Object storage abstraction. The server keeps files on disk; tests use memory. */
export interface BlobStore {
  put(key: string, data: ArrayBuffer, contentType: string): Promise<void>;
  get(key: string): Promise<StoredBlob | null>;
  delete(key: string): Promise<void>;
}

/** Stores objects as files under one directory. Keys are generated by the server, never taken from a client. */
export class FsBlobStore implements BlobStore {
  constructor(private readonly root: string) {}

  private path(key: string): string {
    const target = resolve(this.root, ...key.split("/"));
    if (!target.startsWith(resolve(this.root) + sep)) throw new Error("invalid_blob_key");
    return target;
  }

  async put(key: string, data: ArrayBuffer, contentType: string): Promise<void> {
    const target = this.path(key);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, new Uint8Array(data));
    await writeFile(`${target}.type`, contentType);
  }

  async get(key: string): Promise<StoredBlob | null> {
    const target = this.path(key);
    try {
      const [bytes, type] = await Promise.all([readFile(target), readFile(`${target}.type`, "utf8").catch(() => "application/octet-stream")]);
      return { body: bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer, contentType: type };
    } catch {
      return null;
    }
  }

  async delete(key: string): Promise<void> {
    const target = this.path(key);
    await Promise.all([rm(target, { force: true }), rm(`${target}.type`, { force: true })]);
  }
}

export class MemoryBlobStore implements BlobStore {
  readonly objects = new Map<string, { data: ArrayBuffer; contentType: string }>();

  async put(key: string, data: ArrayBuffer, contentType: string): Promise<void> {
    this.objects.set(key, { data, contentType });
  }

  async get(key: string): Promise<StoredBlob | null> {
    const object = this.objects.get(key);
    return object ? { body: object.data, contentType: object.contentType } : null;
  }

  async delete(key: string): Promise<void> {
    this.objects.delete(key);
  }
}
